def find_tables(obj, path=""):
    results = []
    if isinstance(obj, dict):
        if obj.get('type') == 'table':
            results.append((path, obj))
        for k, v in obj.items():
            results.extend(find_tables(v, path + "." + k))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_tables(v, f"{path}[{i}]"))
    return results

tables = find_tables(data)
print(f"Found {len(tables)} tables")

# Let's look at the content of any table with FFO or fiscal operations
for path, table in tables:
    # Get some content
    if 'content' in table:
        content = str(table.get('content', ''))[:200]
        print(f"Path: {path}, Content preview: {content}")
