python3 << 'EOF'
# Let me check if there are any "Est." labels in the 2014 bulletin beyond 2015
# And also search the full JSON for any year 2025 values

import json

with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Search for any table that might contain fiscal year data beyond 2015
def find_all_years_in_tables(obj, path="", depth=0):
    results = []
    if depth > 5:
        return results
    if isinstance(obj, dict):
        if 'content' in obj and obj['content']:
            content = str(obj['content'])
            # Look for any mention of years like 2016-2025
            for year in range(2016, 2026):
                if str(year) in content and ('surplus' in content.lower() or 'deficit' in content.lower() or 'receipts' in content.lower() or 'outlays' in content.lower()):
                    results.append((path, year, content[:300]))
        for k, v in obj.items():
            results.extend(find_all_years_in_tables(v, path + "." + k, depth+1))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_all_years_in_tables(v, f"{path}[{i}]", depth+1))
    return results

results = find_all_years_in_tables(data)
for r in results:
    print(f"Path: {r[0]}, Year: {r[1]}")
    print(f"Content: {r[2]}")
    print("---")
EOF

python3 << 'EOF'
# Let me look for any U.S. Treasury budget documents or long-term projections
# that might have 2025 estimates

import json

# Search the JSON for any mention of 2025 in tables with surplus/deficit data
with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Let's look specifically at any tables that might have projections
# Check if there are any other pages with tables beyond page 19
def find_all_tables_with_years(obj, path="", depth=0):
    results = []
    if depth > 6:
        return results
    if isinstance(obj, dict):
        if obj.get('type') == 'table' and 'content' in obj:
            content = str(obj['content'])
            # Look for any year in 2015-2030 range in table
            for year in range(2015, 2031):
                if str(year) in content:
                    results.append((path, year, content[:200]))
        for k, v in obj.items():
            results.extend(find_all_tables_with_years(v, path + "." + k, depth+1))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_all_tables_with_years(v, f"{path}[{i}]", depth+1))
    return results

results = find_all_tables_with_years(data)
print(f"Found {len(results)} mentions of years 2015-2030 in tables")
for r in results[:10]:
    print(f"Path: {r[0]}, Year: {r[1]}")
    print(f"Content: {r[2]}")
    print("---")
